export function detectLang() {
  const q = new URLSearchParams(location.search).get('lang'); if (q && T[q]) return q;
  try { const s = localStorage.getItem('geoarch-lang'); if (s && T[s]) return s; } catch {}
  for (const l of navigator.languages || [navigator.language || 'en']) { const k = l.slice(0, 2).toLowerCase(); if (T[k]) return k; if (k === 'be' || k === 'kk') return 'ru'; }
  return 'en';
}
export let LANG = detectLang();
export function setLang(l) { LANG = l; try { localStorage.setItem('geoarch-lang', l); } catch {} }
export function t(key, vars) {
  let s = (T[LANG] && T[LANG][key]) ?? T.en[key] ?? key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.replaceAll('{' + k + '}', v);
  return s;
}
// pick a localized value from {ka, en, ru, ...}
export function L(obj) { if (!obj || typeof obj === 'string') return obj || ''; return obj[LANG] ?? obj.en ?? obj.ka ?? ''; }
